 private int ink=Color.rgb(32,54,52),teal=Color.rgb(40,125,114),bg=Color.rgb(244,247,246); private SharedPreferences prefs;private LinearLayout root;private String lang="fa";
 private String t(String k){int i=Arrays.asList(KEY).indexOf(k);return i<0?k:TR[Arrays.asList(LANG).indexOf(lang)][i];}
 private boolean rtl(){return lang.equals("fa")||lang.equals("ar");}
 private GradientDrawable shape(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(r);return d;}
 private TextView txt(String s,int z,int c,boolean bold){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);if(bold)v.setTypeface(null,1);v.setGravity(rtl()?Gravity.RIGHT:Gravity.LEFT);v.setTextDirection(rtl()?View.TEXT_DIRECTION_RTL:View.TEXT_DIRECTION_LTR);return v;}
 private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setLayoutDirection(rtl()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);return l;}
 private void start(String title,String sub){ScrollView sc=new ScrollView(this);sc.setBackgroundColor(bg);root=col();root.setPadding(20,22,20,28);sc.addView(root);setContentView(sc);LinearLayout top=new LinearLayout(this);top.setGravity(Gravity.CENTER_VERTICAL);top.setOrientation(0);TextView brand=txt(t("brand"),26,ink,true);top.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView language=txt("🌐 "+t("language"),13,teal,true);language.setPadding(10,8,10,8);language.setOnClickListener(v->chooseLanguage());top.addView(language);root.addView(top);TextView s=txt(t("tagline")+" · "+sub,13,Color.GRAY,false);s.setPadding(0,5,0,18);root.addView(s);TextView h=txt(title,21,ink,true);h.setPadding(0,0,0,14);root.addView(h);}
 private void card(String h,String d,Runnable r){LinearLayout c=col();c.setPadding(16,15,16,15);c.setBackground(shape(Color.WHITE,18));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=10;root.addView(c,p);c.addView(txt(h,17,ink,true));TextView v=txt(d,13,Color.GRAY,false);v.setPadding(0,5,0,0);c.addView(v);if(r!=null)c.setOnClickListener(vw->r.run());}
 private EditText field(String hint){EditText e=new EditText(this);e.setSingleLine();e.setHint(hint);e.setTextSize(15);e.setGravity(rtl()?Gravity.RIGHT:Gravity.LEFT);e.setBackground(shape(Color.WHITE,12));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=9;root.addView(e,p);return e;}
 private void btn(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextColor(-1);b.setBackground(shape(teal,15));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,54);p.bottomMargin=12;root.addView(b,p);b.setOnClickListener(v->r.run());}
 private void nav(){TextView v=txt("‹ "+t("back"),14,teal,true);v.setGravity(Gravity.CENTER);v.setPadding(0,20,0,0);root.addView(v);v.setOnClickListener(x->home());}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("hamrah_yar",0);lang=prefs.getString("language","fa");applyDirection();home();}
 private void applyDirection(){getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(bg);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);getWindow().getDecorView().setLayoutDirection(rtl()?View.LAYOUT_DIRECTION_RTL:View.LAYOUT_DIRECTION_LTR);}
 private void chooseLanguage(){String[] names={"فارسی","English","العربية","Deutsch"};new AlertDialog.Builder(this).setTitle(t("chooseLang")).setSingleChoiceItems(names,Arrays.asList(LANG).indexOf(lang),(d,w)->{lang=LANG[w];prefs.edit().putString("language",lang).apply();d.dismiss();applyDirection();home();Toast.makeText(this,t("languageChanged"),Toast.LENGTH_SHORT).show();}).setNegativeButton(t("cancel"),null).show();}
 private String two(int n){return n<10?"0"+n:""+n;}
 private int[] jalali(int gy,int gm,int gd){int[] gdm={0,31,59,90,120,151,181,212,243,273,304,334};if(gm<1||gm>12||gd<1||gd>31)throw new IllegalArgumentException();int y=gy-1600,m=gm-1,d=gd-1;int g=y*365+(y+3)/4-(y+99)/100+(y+399)/400+gdm[m]+d;if(m>1&&((gy%4==0&&gy%100!=0)||gy%400==0))g++;int j=g-79,np=j/12053;j%=12053;int jy=979+33*np+4*(j/1461);j%=1461;if(j>=366){jy+=(j-1)/365;j=(j-1)%365;}int jm,jd;if(j<186){jm=1+j/31;jd=1+j%31;}else{jm=7+(j-186)/30;jd=1+(j-186)%30;}return new int[]{jy,jm,jd};}
 private void home(){Calendar c=Calendar.getInstance();int[] j=jalali(c.get(1),c.get(2)+1,c.get(5));start(t("home"),"");card(t("today")+" · "+j[0]+"/"+two(j[1])+"/"+two(j[2]),t("gregorian")+": "+c.get(1)+"/"+two(c.get(2)+1)+"/"+two(c.get(5)),this::calendar);card(t("calendar"),t("calendarDesc"),this::calendar);card(t("health"),t("healthDesc"),this::health);card(t("reminders"),t("reminderDesc"),this::reminders);card(t("finance"),t("financeDesc"),()->coming("finance"));card(t("education"),t("educationDesc"),()->coming("education"));card(t("maps"),t("mapsDesc"),()->coming("maps"));card(t("places"),t("placesDesc"),()->coming("places"));}
 private void calendar(){start(t("calendar"),t("calendarDesc"));EditText y=field(t("year")),m=field(t("month")),d=field(t("day"));TextView out=txt(t("convertResult"),16,teal,true);root.addView(out);btn(t("convert"),()->{try{int[] a=jalali(Integer.parseInt(y.getText().toString()),Integer.parseInt(m.getText().toString()),Integer.parseInt(d.getText().toString()));out.setText(" "+a[0]+"/"+two(a[1])+"/"+two(a[2]));}catch(Exception e){out.setText(t("invalidDate"));}});card(t("calendar"),t("calendarNext"),null);nav();}
 private void health(){start(t("healthTitle"),t("bmiNote"));EditText h=field(t("height")),w=field(t("weight"));TextView out=txt(t("bmiResult"),16,teal,true);root.addView(out);btn(t("calcBmi"),()->{try{double a=Double.parseDouble(h.getText().toString())/100,b=Double.parseDouble(w.getText().toString());if(a<=0||b<=0)throw new Exception();double v=b/(a*a);String cat=v<18.5?t("bmiUnder"):v<25?t("bmiNormal"):v<30?t("bmiOver"):t("bmiHigh");out.setText(String.format(Locale.US,"BMI: %.1f · %s",v,cat));}catch(Exception e){out.setText(t("invalidDate"));}});card(t("health"),t("healthPrivacy"),null);nav();}
 private void reminders(){start(t("reminderTitle"),t("reminderSub"));LinearLayout list=col();root.addView(list);Set<String> set=new HashSet<>(prefs.getStringSet("items",new HashSet<String>()));for(String s:set){TextView v=txt("• "+s,15,ink,false);v.setPadding(8,12,8,12);list.addView(v);v.setOnLongClickListener(x->{set.remove(s);prefs.edit().putStringSet("items",set).apply();reminders();return true;});}btn(t("addReminder"),()->{EditText e=new EditText(this);e.setHint(t("reminderHint"));new AlertDialog.Builder(this).setTitle(t("addReminder")).setView(e).setNegativeButton(t("cancel"),null).setPositiveButton(t("save"),(x,y)->{String s=e.getText().toString().trim();if(!s.isEmpty()){set.add(s);prefs.edit().putStringSet("items",set).apply();reminders();}}).show();});card(t("reminders"),t("reminderLimit"),null);nav();}
 private void coming(String key){start(t(key),t("comingTitle"));card(t("comingTitle"),t("comingDesc"),null);nav();}
